// Applied rules: [III④, C3, II_vec]
// Skipped rules: [III③: hit [10] is `fread`, which is not covered by the card's supported memory/string replacement templates; hit [11] `strchr` would be subsumed by the III④ slice/iterator rewrite of the delimiter scan, so no standalone III③ rewrite is needed.; II_vec: hit [9] on the fread/capacity-growth loop is abstained: the loop trip count is governed by repeated `fread` results and realloc growth, so canonicalization will not give LLVM a meaningful fixed/derivable iteration count or vectorization opportunity.]
#[inline]
pub unsafe fn choices_fread(
    mut c: *mut choices_t,
    mut file: *mut FILE,
    mut input_delimiter: c_char,
) {
    let mut buffer_size: size_t = (*c).buffer_size;
    let buffer_start: size_t = buffer_size;
    let mut capacity: size_t = INITIAL_BUFFER_CAPACITY as size_t;
    while capacity <= buffer_size {
        capacity = capacity.wrapping_mul(2 as size_t);
    }

    let mut buffer =
        safe_realloc((*c).buffer as *mut c_void, capacity) as *mut c_char;
    (*c).buffer = buffer;

    loop {
        let read_ptr = buffer.offset(buffer_size as isize) as *mut c_void;
        let remaining = capacity.wrapping_sub(buffer_size);
        buffer_size = (buffer_size as c_ulong)
            .wrapping_add(fread(read_ptr, 1 as size_t, remaining, file))
            as size_t as size_t;
        (*c).buffer_size = buffer_size;
        if !(buffer_size == capacity) {
            break;
        }
        capacity = capacity.wrapping_mul(2 as size_t);
        buffer = safe_realloc(buffer as *mut c_void, capacity) as *mut c_char;
        (*c).buffer = buffer;
    }

    buffer = safe_realloc(
        buffer as *mut c_void,
        buffer_size.wrapping_add(1 as size_t),
    ) as *mut c_char;
    (*c).buffer = buffer;

    let nul_pos = buffer_size;
    buffer_size = buffer_size.wrapping_add(1);
    (*c).buffer_size = buffer_size;
    *buffer.offset(nul_pos as isize) = '\0' as i32 as c_char;

    let appended_len = buffer_size.wrapping_sub(buffer_start);
    // SAFETY: `buffer` is the current allocation stored in `(*c).buffer`, non-null as returned
    // by `safe_realloc`; `buffer_start..buffer_start+appended_len` lies within that allocation
    // because `buffer_size` was just finalized from the same allocation; this function creates
    // the only mutable view over that region for the duration of the scan.
    let appended = unsafe {
        core::slice::from_raw_parts_mut(
            buffer.offset(buffer_start as isize),
            appended_len,
        )
    };

    let delim = input_delimiter;
    let mut line_start = 0usize;
    for i in 0..appended_len {
        if *appended.get_unchecked(i) == delim || *appended.get_unchecked(i) == 0 {
            if *appended.get_unchecked(line_start) != 0 {
                let line_ptr = appended.as_mut_ptr().add(line_start);
                if *appended.get_unchecked(i) == delim {
                    *appended.get_unchecked_mut(i) = 0;
                }
                choices_add(c, line_ptr);
            } else if *appended.get_unchecked(i) == delim {
                *appended.get_unchecked_mut(i) = 0;
            }
            line_start = i.wrapping_add(1);
        }
    }
}

